SmsParserDeviceTemplate.Script:
log("Hello from SMS Parser");
log("Address: " + address);
log("Text: " + text);

const arr = text.split(/\s+/);
let idx = 0;

for (const elem of arr) {
  setTagValue(idx, Number(arr[idx]));
}

if (text.includes("Alarm")) {
  setEventStatus(23);
} else {
  setEventStatus(1);
}
